mapper.select:
SELECT event_id, cdc_run_id, table_name, op, CAST(payload AS TEXT) AS payload, attempts
  FROM cdc_event
 WHERE cdc_run_id = #{cdcRunId} AND status = #{status}
 ORDER BY event_id
 LIMIT #{limit}

SELECT event_id, table_name, op, source_key, status, attempts, duplicate_count, last_error, topic, kafka_partition,
       kafka_offset, source_lsn, received_at, applied_at, CAST(payload AS TEXT) AS payload
  FROM cdc_event
 WHERE cdc_run_id = #{cdcRunId}
AND status = #{status}
 ORDER BY event_id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
  FROM cdc_event
 WHERE cdc_run_id = #{cdcRunId}
AND status = #{status}
